/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Determinant, E, ImmutableDenseMatrix, MatAdd, MatMul, Matrix, MatrixElement, MatrixGamma, MatrixGammaDistribution, MatrixNormal, MatrixNormalDistribution, MatrixStudentT, MatrixStudentTDistribution, MatrixSymbol, Mul, Pow, Sym, Trace, Transpose, Wishart, WishartDistribution, add, doit, fn, mul, pi, pow, rational } from '../../src';
import { sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.stats.matrix_distributions", () => {
  it("density(M)([[1, 0], [0, 1]]).doit()", () => {
    const b = new Sym('b', { positive: true });
    const a = new Sym('a', { positive: true });
    expect(sympyStr(doit(mul(pow(pi, rational(-1, 2)), pow(b, mul(-2, a)), pow(Determinant(Matrix.of([[rational(1), rational(0)], [rational(0), rational(1)]])), add(rational(-3, 2), a)), pow(Determinant(Matrix.of([[rational(2), rational(1)], [rational(1), rational(2)]])), mul(-1, a)), pow(fn('gamma', [a]), -1), pow(fn('gamma', [add(rational(-1, 2), a)]), -1), new Pow(E, Trace(Matrix.of([[mul(rational(-2, 3), pow(b, -1)), mul(rational(1, 3), pow(b, -1))], [mul(rational(1, 3), pow(b, -1)), mul(rational(-2, 3), pow(b, -1))]]))))))).toBe('exp(-4/(3*b))/(3**a*sqrt(pi)*b**(2*a)*gamma(a)*gamma(a - 1/2))');
  });
  it("density(M)([[3, 4]]).doit()", () => {
    expect(sympyStr(doit(mul(rational(1, 2), pow(pi, -1), pow(Determinant(Matrix.of([[rational(1)]])), -1), pow(Determinant(Matrix.of([[rational(1), rational(0)], [rational(0), rational(1)]])), rational(-1, 2)), new Pow(E, mul(rational(-1, 2), Trace(Matrix.of([[rational(4), rational(4)], [rational(4), rational(4)]])))))))).toBe('exp(-4)/(2*pi)');
  });
  it("density(W)([[1, 0], [0, 1]]).doit()", () => {
    const n = new Sym('n', { positive: true });
    expect(sympyStr(doit(mul(pow(2, mul(-1, n)), pow(pi, rational(-1, 2)), pow(Determinant(Matrix.of([[rational(1), rational(0)], [rational(0), rational(1)]])), add(rational(-3, 2), mul(rational(1, 2), n))), pow(Determinant(Matrix.of([[rational(2), rational(1)], [rational(1), rational(2)]])), mul(rational(-1, 2), n)), pow(fn('gamma', [mul(rational(1, 2), n)]), -1), pow(fn('gamma', [add(rational(-1, 2), mul(rational(1, 2), n))]), -1), new Pow(E, Trace(Matrix.of([[rational(-1, 3), rational(1, 6)], [rational(1, 6), rational(-1, 3)]]))))))).toBe('exp(-2/3)/(2**n*3**(n/2)*sqrt(pi)*gamma(n/2)*gamma(n/2 - 1/2))');
  });
  it("density(M)(X).doit()", () => {
    const b = new Sym('b', { positive: true });
    const a = new Sym('a', { positive: true });
    expect(sympyMatches(doit(mul(pow(pi, rational(-1, 2)), pow(b, mul(-2, a)), pow(Determinant(Matrix.of([[rational(2), rational(1)], [rational(1), rational(2)]])), mul(-1, a)), pow(Determinant(new MatrixSymbol('X', rational(2), rational(2))), add(rational(-3, 2), a)), pow(fn('gamma', [a]), -1), pow(fn('gamma', [add(rational(-1, 2), a)]), -1), new Pow(E, Trace(MatMul(pow(b, -1), Matrix.of([[rational(-2, 3), rational(1, 3)], [rational(1, 3), rational(-2, 3)]]), new MatrixSymbol('X', rational(2), rational(2))))))), 'exp(Trace(Matrix([\n[-2/3,  1/3],\n[ 1/3, -2/3]])*X)/b)*Determinant(X)**(a - 3/2)/(3**a*sqrt(pi)*b**(2*a)*gamma(a)*gamma(a - 1/2))')).toBe(true);
  });
  it("density(M)(X).doit() (2)", () => {
    expect(sympyMatches(doit(mul(rational(1, 2), pow(pi, -1), pow(Determinant(Matrix.of([[rational(1)]])), -1), pow(Determinant(Matrix.of([[rational(1), rational(0)], [rational(0), rational(1)]])), rational(-1, 2)), new Pow(E, mul(rational(-1, 2), Trace(MatMul(MatAdd(Matrix.of([[rational(-1)], [rational(-2)]]), Transpose(new MatrixSymbol('X', rational(1), rational(2)))), MatAdd(Matrix.of([[rational(-1), rational(-2)]]), new MatrixSymbol('X', rational(1), rational(2))))))))), 'exp(-Trace((Matrix([\n[-1],\n[-2]]) + X.T)*(Matrix([[-1, -2]]) + X))/2)/(2*pi)')).toBe(true);
  });
  it("density(M)(X)", () => {
    const v = new Sym('v', { positive: true });
    expect(sympyMatches(new MatrixStudentTDistribution([v, ImmutableDenseMatrix(Matrix.of([[rational(1), rational(2)]])), ImmutableDenseMatrix(Matrix.of([[rational(1), rational(0)], [rational(0), rational(1)]])), ImmutableDenseMatrix(Matrix.of([[rational(1)]]))]).call(new MatrixSymbol('X', rational(1), rational(2))), 'gamma(v/2 + 1)*Determinant((Matrix([[-1, -2]]) + X)*(Matrix([\n[-1],\n[-2]]) + X.T) + Matrix([[1]]))**(-v/2 - 1)/(pi**1.0*gamma(v/2)*Determinant(Matrix([[1]]))**1.0*Determinant(Matrix([\n[1, 0],\n[0, 1]]))**0.5)')).toBe(true);
  });
  it("density(W)(X).doit()", () => {
    const n = new Sym('n', { positive: true });
    expect(sympyMatches(doit(mul(pow(2, mul(-1, n)), pow(pi, rational(-1, 2)), pow(Determinant(Matrix.of([[rational(2), rational(1)], [rational(1), rational(2)]])), mul(rational(-1, 2), n)), pow(Determinant(new MatrixSymbol('X', rational(2), rational(2))), add(rational(-3, 2), mul(rational(1, 2), n))), pow(fn('gamma', [mul(rational(1, 2), n)]), -1), pow(fn('gamma', [add(rational(-1, 2), mul(rational(1, 2), n))]), -1), new Pow(E, Trace(MatMul(Matrix.of([[rational(-1, 3), rational(1, 6)], [rational(1, 6), rational(-1, 3)]]), new MatrixSymbol('X', rational(2), rational(2))))))), 'exp(Trace(Matrix([\n[-1/3,  1/6],\n[ 1/6, -1/3]])*X))*Determinant(X)**(n/2 - 3/2)/(2**n*3**(n/2)*sqrt(pi)*gamma(n/2)*gamma(n/2 - 1/2))')).toBe(true);
  });
});

